    [Theory]
    [MemberData(nameof(Mistakes))]
    public void AMatchChargedAsAnEditIsFound(string fileName, string code, string check, int line, int changeAt, int removed, string added)
    {
        var found = Assert.Single(LogicPatterns.All.Where(pattern => pattern.Id == check).SelectMany(pattern => pattern.Find(Program(fileName, code))));

        Assert.Equal(line, found.Line);
        Assert.Equal(changeAt, found.Fix!.StartLine);
        Assert.Equal(removed, found.Fix.RemoveCount);
        Assert.Equal(added.Split('\n'), found.Fix.NewLines);
    }

    /// <summary>
    /// The programs charging nothing for a match; the shortest common supersequence, whose match does add one, as a table and
    /// as a function calling itself; and the fewest items deleted from both to make them equal.
    /// </summary>
    [Theory]
    [InlineData("distance.c", "#include <stdio.h>\n#include <string.h>\n\n#define MIN3(a, b, c) ((a) < (b) ? ((a) < (c) ? (a) : (c)) : ((b) < (c) ? (b) : (c)))\n\nint edit_distance(const char *first, const char *second) {\n    static int table[16][16];\n    int rows = (int) strlen(first), cols = (int) strlen(second);\n    for (int i = 0; i <= rows; i++) table[i][0] = i;\n    for (int j = 0; j <= cols; j++) table[0][j] = j;\n    for (int i = 1; i <= rows; i++) {\n        for (int j = 1; j <= cols; j++) {\n            if (first[i - 1] == second[j - 1]) {\n                table[i][j] = table[i - 1][j - 1];\n            } else {\n                table[i][j] = 1 + MIN3(table[i - 1][j], table[i][j - 1], table[i - 1][j - 1]);\n            }\n        }\n    }\n    return table[rows][cols];\n}\n\nint main(void) {\n    printf(\"%d\\n\", edit_distance(\"kitten\", \"sitting\"));\n    return 0;\n}\n")]
